factorial.code:
with Ada.Text_IO;         use Ada.Text_IO;
with Ada.Integer_Text_IO; use Ada.Integer_Text_IO;

procedure Factorial is
   function Fact (N : Natural) return Positive is
   begin
      if N <= 1 then
         return 1;
      else
         return N * Fact (N - 1);
      end if;
   end Fact;
begin
   Put (Fact (10), Width => 0);
   New_Line;
end Factorial;

fizzbuzz.code:
with Ada.Text_IO;         use Ada.Text_IO;
with Ada.Integer_Text_IO; use Ada.Integer_Text_IO;

procedure FizzBuzz is
begin
   for I in 1 .. 15 loop
      if I mod 15 = 0 then
         Put ("FizzBuzz");
      elsif I mod 3 = 0 then
         Put ("Fizz");
      elsif I mod 5 = 0 then
         Put ("Buzz");
      else
         Put (I, Width => 0);
      end if;
      New_Line;
   end loop;
end FizzBuzz;

higher-order.code:
with Ada.Text_IO;         use Ada.Text_IO;
with Ada.Integer_Text_IO; use Ada.Integer_Text_IO;

procedure Map_Filter is
   type Int_Array is array (Positive range <>) of Integer;
   Numbers : constant Int_Array := [for I in 1 .. 10 => I];  -- Ada 2022 aggregate
   First   : Boolean := True;
begin
   for N of Numbers when N mod 2 = 0 loop                   -- Ada 2022 filter
      if not First then
         Put (" ");
      end if;
      Put (N * N, Width => 0);
      First := False;
   end loop;
   New_Line;
end Map_Filter;

shapes.code:
with Ada.Text_IO; use Ada.Text_IO;

procedure Shapes is
   package Geometry is
      type Shape is abstract tagged null record;
      function Area (S : Shape) return Natural is abstract;
      function Name (S : Shape) return String is abstract;

      type Rectangle is new Shape with record
         Width, Height : Natural;
      end record;
      overriding function Area (R : Rectangle) return Natural is (R.Width * R.Height);
      overriding function Name (R : Rectangle) return String is ("Rectangle");

      type Triangle is new Shape with record
         Base, Height : Natural;
      end record;
      overriding function Area (T : Triangle) return Natural is (T.Base * T.Height / 2);
      overriding function Name (T : Triangle) return String is ("Triangle");
   end Geometry;
   use Geometry;

   procedure Show (S : Shape'Class) is   -- class-wide: calls dispatch at run time
   begin
      Put_Line (S.Name & ":" & Natural'Image (S.Area));
   end Show;
begin
   Show (Rectangle'(Width => 3, Height => 4));
   Show (Triangle'(Base => 10, Height => 3));
end Shapes;

signature.code:
with Ada.Text_IO; use Ada.Text_IO;

procedure Strong_Types is
   type Celsius is range -273 .. 1_000;   -- a new integer type with its own range
   type Floor   is range -2 .. 120;       -- also an integer, but a distinct type
   type Day     is (Mon, Tue, Wed, Thu, Fri, Sat, Sun);
   subtype Weekend is Day range Sat .. Sun;

   Temp : Celsius := 20;
begin
   --  Temp := Floor'(3);   -- rejected at compile time: Floor is not Celsius
   for D in Weekend loop
      Put_Line (Day'Image (D) & " is day" & Integer'Image (Day'Pos (D) + 1));
   end loop;
   Temp := Temp - 300;                    -- -280 is out of range: checked at run time
   Put_Line ("unreachable" & Celsius'Image (Temp));
exception
   when Constraint_Error =>
      Put_Line ("Constraint_Error: Celsius must stay within -273 .. 1000");
end Strong_Types;
